begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.ma(t text) returns uuid language sql immutable as $$select md5('member-agenda-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.ma(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.ma(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-agenda@example.invalid',case when t='unconfirmed' then null else now() end,now(),now() from unnest(array['owner','member','second','outside','unconfirmed']) t;
insert into public.organizations(id,name,slug,status) values(pg_temp.ma('org'),'Agenda fictícia','member-agenda-test','active'),(pg_temp.ma('other'),'Outro ministério','member-agenda-other','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.ma('unit'),pg_temp.ma('org'),'Igreja fictícia A','a','headquarters'),(pg_temp.ma('unitb'),pg_temp.ma('org'),'Igreja fictícia B','b','campus'),(pg_temp.ma('unitc'),pg_temp.ma('other'),'Igreja externa','c','headquarters');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) select pg_temp.ma(t||'-m'),pg_temp.ma('org'),pg_temp.ma(t),pg_temp.ma('unit'),case when t='owner' then 'owner'::public.membership_role else 'member'::public.membership_role end,'active' from unnest(array['owner','member','second'])t;
insert into public.people(id,organization_id,unit_id,auth_user_id,full_name,status) select pg_temp.ma(t||'-p'),pg_temp.ma('org'),pg_temp.ma('unit'),pg_temp.ma(t),t||' fictício','active' from unnest(array['member','second'])t;
insert into private.church_app_events(id,organization_id,unit_id,title,kind,starts_at,ends_at,capacity) values(pg_temp.ma('event'),pg_temp.ma('org'),pg_temp.ma('unit'),'Encontro fictício','event',now()+interval '1 hour',now()+interval '3 hours',1),(pg_temp.ma('draftb'),pg_temp.ma('org'),pg_temp.ma('unitb'),'Rascunho secreto','service',now()+interval '2 days',now()+interval '3 days',10);
create function pg_temp.admin(a text,v integer default null,d jsonb default '{}') returns jsonb language sql as $$select public.member_agenda_admin(pg_temp.ma('org'),pg_temp.ma('unit'),a,pg_temp.ma('event'),v,d)$$;
create function pg_temp.self(a text,id uuid default null,d jsonb default '{}') returns jsonb language sql as $$select public.member_agenda_self(pg_temp.ma('org'),a,pg_temp.ma('unit'),id,d)$$;
create function pg_temp.regid(t text) returns uuid language sql security definer as $$select id from private.church_app_registrations where user_id=pg_temp.ma(t) and event_id=pg_temp.ma('event')$$;
create function pg_temp.code(t text) returns uuid language sql security definer as $$select code from private.church_app_registrations where user_id=pg_temp.ma(t) and event_id=pg_temp.ma('event')$$;
select ok(not has_table_privilege('authenticated','private.church_app_registrations','select'),'inscrições sem leitura direta');
select ok(not has_table_privilege('anon','private.member_inbox_reads','select'),'recibos privados');
select ok(not has_function_privilege('anon','public.member_agenda_self(uuid,text,uuid,uuid,jsonb)','execute'),'visitante não inscreve conta');
set local role anon;
select is(jsonb_array_length(public.member_agenda(pg_temp.ma('org'),pg_temp.ma('unit'))->'items'),0,'rascunho não aparece');
select is(public.member_agenda(pg_temp.ma('org'),pg_temp.ma('unitc'))->>'available','false','unidade de outro ministério não expõe agenda');
reset role;
select pg_temp.actor('owner');
set local role authenticated;
select lives_ok($$select pg_temp.admin('list')$$,'admin consulta agenda');
select lives_ok($$select pg_temp.admin('publish',1)$$,'publicação autorizada');
select throws_ok($$select pg_temp.admin('cancel',1)$$,'40001','member_event_changed','versão antiga não cancela');
select lives_ok($$select public.member_agenda_admin(pg_temp.ma('org'),pg_temp.ma('unit'),'create',null,null,jsonb_build_object('title','Novo culto fictício','description','Teste','kind','service','startsLocal',to_char((now()+interval '2 days') at time zone 'America/Sao_Paulo','YYYY-MM-DD"T"HH24:MI'),'endsLocal',to_char((now()+interval '2 days 2 hours') at time zone 'America/Sao_Paulo','YYYY-MM-DD"T"HH24:MI'),'location','Salão fictício','address','Endereço fictício','capacity',20))$$,'evento criado com horário de Brasília');
select throws_ok($$select public.member_agenda_admin(pg_temp.ma('org'),pg_temp.ma('unitc'),'list')$$,'42501','member_agenda_denied','admin não gerencia outro ministério');
set local role anon;
select is(jsonb_array_length(public.member_agenda(pg_temp.ma('org'),pg_temp.ma('unit'))->'items'),1,'publicação visível sem login');
select ok(not public.member_agenda(pg_temp.ma('org'),pg_temp.ma('unit'))::text like '%agenda@example%','agenda pública sem contatos pessoais');
reset role;
select pg_temp.actor('unconfirmed');
set local role authenticated;
select throws_ok($$select pg_temp.self('register',pg_temp.ma('event'))$$,'42501',null,'e-mail não confirmado recusado');
select pg_temp.actor('outside');
select throws_ok($$select pg_temp.self('register',pg_temp.ma('event'))$$,'42501','member_registration_identity','conta sem identidade conferida não se inscreve');
select pg_temp.actor('member');
select throws_ok($$select pg_temp.admin('list')$$,'42501','member_agenda_denied','membro não acessa inscritos');
select lives_ok($$select pg_temp.self('register',pg_temp.ma('event'))$$,'inscrição gratuita confirmada');
select lives_ok($$select pg_temp.self('register',pg_temp.ma('event'))$$,'repetição idempotente');
select is(jsonb_array_length(pg_temp.self('tickets')->'items'),1,'uma conta mantém um ticket');
select ok(pg_temp.self('tickets')->'items'->0->>'code' is not null,'código disponível ao próprio titular');
select ok((pg_temp.self('inbox')->'items')::text like '%inscrição gratuita%','confirmação na caixa de entrada');
select lives_ok($$select pg_temp.self('read',null,jsonb_build_object('keys',(select jsonb_agg(x->>'message_key') from jsonb_array_elements(pg_temp.self('inbox')->'items')x)))$$,'marca apenas mensagens visíveis');
select ok(not exists(select 1 from jsonb_array_elements(pg_temp.self('inbox')->'items')x where x->>'read'<>'true'),'mensagens marcadas como lidas');
select throws_ok($$select pg_temp.self('read',null,'{"keys":["profile:outra-conta"]}')$$,'40001','member_inbox_changed','chave forjada recusada');
select pg_temp.actor('second');
select is(jsonb_array_length(pg_temp.self('tickets')->'items'),0,'outra conta não vê ticket alheio');
select throws_ok($$select pg_temp.self('register',pg_temp.ma('event'))$$,'40001','member_event_full','limite de vagas respeitado');
select throws_ok($$select pg_temp.self('cancel',pg_temp.regid('member'))$$,'42501','member_agenda_denied','não cancela ticket alheio');
select pg_temp.actor('member');
select lives_ok($$select pg_temp.self('cancel',pg_temp.regid('member'))$$,'cancelamento libera vaga');
select is(pg_temp.self('tickets')->'items'->0->>'code',null,'ticket cancelado não mostra código');
select pg_temp.actor('second');
select lives_ok($$select pg_temp.self('register',pg_temp.ma('event'))$$,'outra conta ocupa vaga liberada');
reset role;
select is((select count(*)::integer from private.church_app_registrations where event_id=pg_temp.ma('event') and status='confirmed'),1,'apenas uma vaga ocupada');
select pg_temp.actor('owner');
set local role authenticated;
select lives_ok($$select pg_temp.admin('checkin',null,jsonb_build_object('code',pg_temp.code('second')))$$,'check-in com código válido');
select is(pg_temp.admin('checkin',null,jsonb_build_object('code',pg_temp.code('second')))->>'already','true','código repetido não duplica entrada');
select pg_temp.actor('second');
select throws_ok($$select pg_temp.self('cancel',pg_temp.regid('second'))$$,'40001','member_cancel_closed','não cancela depois da entrada');
select ok((pg_temp.self('inbox')->'items')::text like '%entrada foi confirmada%','entrada gera notificação interna');
reset role;
select pg_temp.actor('owner');
set local role authenticated;
select lives_ok($$select pg_temp.admin('cancel',2)$$,'cancelamento do evento auditado');
select pg_temp.actor('second');
select is(pg_temp.self('tickets')->'items'->0->>'code',null,'evento cancelado invalida apresentação');
select ok((pg_temp.self('inbox')->'items')::text like '%Evento cancelado%','cancelamento aparece como notificação nova');
reset role;
select ok(exists(select 1 from public.audit_logs where organization_id=pg_temp.ma('org') and action='member.agenda.register'),'inscrição auditada');
select is((select unit_id from public.people where id=pg_temp.ma('member-p')),pg_temp.ma('unit'),'inscrição não transfere membro');
select * from finish();
rollback;
